import React, { useState } from "react";
import Swal from "sweetalert2";
import { Card, CardContent } from "../ui/card";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../ui/dropdown-menu";
import {
  Calendar,
  Clock,
  Shield,
  CheckCircle,
  Users,
  Briefcase,
  MoreVertical,
  Edit,
  Trash2,
} from "lucide-react";
import { getStatusColor } from "../../utils/formatters";
import { formatDate, formatCurrency } from "../../utils/formatters";
import { projectService } from "../../services/projectService";
import { useAuth } from "../../contexts/AuthContext";

const getProjectTypeIcon = (type) => {
  const icons = {
    audit: Shield,
    certification: CheckCircle,
    consulting: Users,
    training: Briefcase,
  };
  const Icon = icons[type] || Shield;
  return <Icon className="w-4 h-4" />;
};

const getStatusLabel = (status) => {
  const labels = {
    planning: "Planeación",
    in_progress: "En Progreso",
    completed: "Completado",
    cancelled: "Cancelado",
  };
  return labels[status] || status;
};

export const ProjectCard = ({ project, onViewDetails, onUpdate }) => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const isAdmin = ["super_admin", "admin"].includes(user?.role);

  const handleStatusChange = async (newStatus) => {
    if (!isAdmin) return;

    const confirmMessage = `¿Está seguro de cambiar el estado a "${getStatusLabel(
      newStatus
    )}"?`;
    if (!window.confirm(confirmMessage)) return;

    setLoading(true);
    try {
      await projectService.updateStatus(project._id, newStatus);
      Swal.fire({
        position: "center",
        icon: "success",
        title: "Tu estado ha sido actualizado",
        showConfirmButton: false,
        timer: 1500,
      });
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error("Error updating status:", error);
      alert(error.response?.data?.detail || "Error al actualizar estado");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className={loading ? "opacity-50" : ""}>
      <CardContent className="p-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4 flex-1">
            <div className="p-2 bg-green-100 rounded-lg">
              {getProjectTypeIcon(project.project_type)}
            </div>
            <div className="flex-1">
              <h3 className="text-lg font-semibold text-gray-900">
                {project.project_name}
              </h3>
              <p className="text-sm text-gray-600">{project.description}</p>
              <div className="flex items-center gap-2 mt-1">
                <p className="text-sm text-gray-500 capitalize">
                  {project.project_type.replace("_", " ")}
                </p>
                {project.client_id && (
                  <>
                    <span className="text-gray-400">•</span>
                    <p className="text-sm text-gray-500">
                      {project.client_id.company_name}
                    </p>
                  </>
                )}
              </div>
            </div>
          </div>

          <div className="text-right flex items-start gap-3">
            <div>
              {/* Status Dropdown */}
              {isAdmin ? (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild disabled={loading}>
                    <button
                      className={`${getStatusColor(
                        project.status
                      )} px-3 py-1 rounded-full text-xs font-semibold cursor-pointer hover:opacity-80 transition-opacity`}
                    >
                      {getStatusLabel(project.status)} ▾
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("planning")}
                      disabled={project.status === "planning"}
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-yellow-500"></div>
                        Planeación
                      </div>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("in_progress")}
                      disabled={project.status === "in_progress"}
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                        En Progreso
                      </div>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("completed")}
                      disabled={project.status === "completed"}
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-green-500"></div>
                        Completado
                      </div>
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => handleStatusChange("cancelled")}
                      disabled={project.status === "cancelled"}
                      className="text-red-600"
                    >
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-red-500"></div>
                        Cancelado
                      </div>
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              ) : (
                <Badge className={getStatusColor(project.status)}>
                  {getStatusLabel(project.status)}
                </Badge>
              )}

              <p className="text-lg font-bold text-gray-900 mt-2">
                {formatCurrency(project.budget)}
              </p>
            </div>

            {/* Menu de opciones */}
            {isAdmin && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                    <MoreVertical className="h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuItem onClick={() => onViewDetails?.(project)}>
                    <Edit className="w-4 h-4 mr-2" />
                    Editar
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    className="text-red-600"
                    onClick={() => {
                      if (
                        window.confirm(
                          "¿Está seguro de eliminar este proyecto?"
                        )
                      ) {
                        // Aquí irá la función de eliminar
                        alert("Función de eliminar pendiente");
                      }
                    }}
                  >
                    <Trash2 className="w-4 h-4 mr-2" />
                    Eliminar
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
        </div>

        <div className="mt-4 flex items-center justify-between text-sm text-gray-600">
          <div className="flex items-center space-x-4">
            <p className="flex items-center">
              <Calendar className="w-4 h-4 mr-2" />
              Inicio: {formatDate(project.start_date)}
            </p>
            <p className="flex items-center">
              <Clock className="w-4 h-4 mr-2" />
              {project.status === "completed" && project.actual_end_date
                ? `Finalizado: ${formatDate(project.actual_end_date)}`
                : `Estimado: ${formatDate(project.estimated_end_date)}`}
            </p>
          </div>
          {onViewDetails && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => onViewDetails(project)}
            >
              Ver Detalles
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  );
};
